        "Muodot: strömt aus, strömte aus. Kun jokin virtaa ulos eli kyse on liikkeestä, perfektin apuverbi on sein: Das Gas ist ausgeströmt. Akkusatiiviobjektin kanssa (Ruhe ausströmen) käytetään apuverbiä haben: Sie hat Ruhe ausgeströmt.",
        "Sana on lähellä verbiä strömen (virrata). Yleisimmät käyttötavat ovat tekniset, kun puhutaan kaasuvuodosta, ja kuvaannolliset, kun puhutaan ihmisen luomasta vaikutelmasta."
