        "Muodot: tritt aus, trat aus. Eroaminen: Er ist aus dem Verein ausgetreten (aus + datiivi). Ulos purkautuminen: Gas ist ausgetreten. Tallaaminen: Er hat die Zigarette ausgetreten (sammutti sen polkemalla).",
        "Partisiippi ausgetreten kuvaa adjektiivina kulunutta, tallattua paikkaa: ausgetretene Stufen (kuluneet portaat)."
