        "Muodot: begnügt sich, begnügte sich, hat sich begnügt. Etuliite be- on erottamaton, joten ge-ainesta ei tule.",
        "mit-preposition jälkeen tulee substantiivi tai pronomini (damit) tai infinitiivirakenne: sich damit begnügen, etwas zu tun (tyytyä siihen, että tekee jotakin)."
