        "Muodot: beschränkt sich, beschränkte sich, hat sich beschränkt. Etuliite be- on erottamaton, joten ge-ainesta ei tule.",
        "Ilman sich-pronominia beschränken tarkoittaa rajoittaa jotakin muuta: die Zahl beschränken. Asioista, jotka rajoittuvat johonkin, käytetään rakennetta sich beschränken auf: Das Problem beschränkt sich auf …"
