      "explanation": [
        "Perusajatus: das Hochwasser on neutrisubstantiivi. Se tarkoittaa hyvin korkeaa vedenpintaa joessa, meressä tai järvessä ja sen aiheuttamaa tulvaa. Monikko on die Hochwasser (myös Hochwässer).",
        "Yleisiä ilmauksia: Hochwasser führen (joessa on korkea vedenpinta), vor Hochwasser warnen (varoittaa tulvasta), vom Hochwasser betroffen sein (kärsiä tulvasta). Vastakohta on das Niedrigwasser."
      ],
      "examples": [
        {
          "de": "Nach dem Regen gibt es Hochwasser.",
          "lv": "Sateen jälkeen on tulva."
        },
        {
          "de": "Der Fluss führt Hochwasser.",
          "lv": "Joessa on korkea vedenpinta."
        },
        {
          "de": "Die Behörden warnen vor Hochwasser.",
          "lv": "Viranomaiset varoittavat tulvasta."
        },
        {
          "de": "Das Hochwasser hat mehrere Dörfer erreicht.",
          "lv": "Tulva on saavuttanut useita kyliä."
        }
      ],
      "comparison": [
        {
          "word": "die Überschwemmung",
          "meaning": "tulviminen, tulvavahinko",
          "example": "Die Überschwemmung zerstörte die Ernte. – Tulva tuhosi sadon."
        },
        {
          "word": "die Flut",
          "meaning": "nousuvesi",
          "example": "Die Flut kommt am Abend. – Nousuvesi tulee illalla."
        },
        {
          "word": "das Niedrigwasser",
          "meaning": "matala vedenpinta",
          "example": "Bei Niedrigwasser fahren weniger Schiffe. – Matalan veden aikaan liikkuu vähemmän laivoja."
        }
      ],
      "tip": [
        "Muista vastakohta: Hochwasser — Niedrigwasser.",
        "Uutisissa kuulet usein sanat Hochwasserwarnung ja Hochwasserschutz."
      ],
      "important": [
        "Hochwasser ei ole sama kuin Flut (meren nousuvesi).",
        "Monikossa artikkeli on die, mutta sana itse pysyy muuttumattomana: die Hochwasser."
      ],
